365. async function readStartupMetrics(page, client) {
366.   await page.waitForFunction(() => {
367.     const state = globalThis.__2dndPerformanceBaseline;
368.     return typeof state?.titleReadyMs === "number";
369.   });
370.   await page.waitForLoadState("load");
371.   await page.evaluate(() => {
372.     if (typeof globalThis.gc === "function") globalThis.gc();
373.   });
374.   await page.waitForTimeout(50);
375. 
376.   const [heap, dom, browserMetrics] = await Promise.all([
377.     client.send("Runtime.getHeapUsage"),
378.     client.send("Memory.getDOMCounters"),
379.     page.evaluate((measureName) => {
380.       const navigation = performance.getEntriesByType("navigation").at(-1);

381.       const bootMeasure = performance.getEntriesByName(measureName).at(-1);
382.       const state = globalThis.__2dndPerformanceBaseline;
383.       if (!(navigation instanceof PerformanceNavigationTiming)) {
384.         throw new Error("Missing navigation performance entry");
385.       }
386.       if (!(bootMeasure instanceof PerformanceMeasure)) {
387.         throw new Error(`Missing ${measureName} performance measure`);
388.       }
389.       if (typeof state?.titleReadyMs !== "number") {
390.         throw new Error("Missing title-ready performance marker");
391.       }
392.       const resources = performance.getEntriesByType("resource");
393.       return {
394.         titleReadyMs: state.titleReadyMs,
395.         bootTexturesMs: bootMeasure.duration,
396.         domContentLoadedMs: navigation.domContentLoadedEventEnd,
397.         loadEventMs: navigation.loadEventEnd,
398.         titleAfterDomContentLoadedMs:
399.           state.titleReadyMs - navigation.domContentLoadedEventEnd,
400.         transferBytes:
401.           navigation.transferSize
402.           + resources.reduce((total, entry) => {
403.             return total + (
404.               entry instanceof PerformanceResourceTiming ? entry.transferSize : 0
405.             );
406.           }, 0),
407.         decodedBodyBytes:
408.           navigation.decodedBodySize
409.           + resources.reduce((total, entry) => {
410.             return total + (
411.               entry instanceof PerformanceResourceTiming
412.                 ? entry.decodedBodySize
413.                 : 0
414.             );
415.           }, 0),
416.       };
417.     }, BOOT_TEXTURE_MEASURE),
418.   ]);
419. 
420.   return {
421.     ...browserMetrics,
422.     jsHeapUsedBytes: heap.usedSize,
423.     jsHeapTotalBytes: heap.totalSize,
424.     documents: dom.documents,
425.     domNodes: dom.nodes,
426.     jsEventListeners: dom.jsEventListeners,
427.   };
428. }
