464. async function createFreshSave(browser, url) {
465.   const context = await prepareContext(browser, url, null);
466.   try {
467.     const page = await context.newPage();
468.     const client = await context.newCDPSession(page);
469.     await client.send("Network.enable");
470.     await client.send("Network.setCacheDisabled", { cacheDisabled: true });
471.     await page.goto(url, { waitUntil: "domcontentloaded" });
472.     await waitForState(page, "BOOT | Screen: title");
473.     await clickGame(page, 320, 324);
474.     await waitForState(page, "BOOT | Screen: character");
475.     await page.waitForTimeout(100);
476.     await page.keyboard.press("Enter");
477.     await waitForState(page, "BOOT | Screen: stats");
478.     await clickGame(page, 390, 64);
479.     await clickGame(page, 400, 460);
480.     await waitForState(page, "BOOT | Screen: appearance");
481.     await clickGame(page, 420, 312);
482.     await waitForState(page, "CUTSCENE | campaign.opening");
483. 
484.     return await page.evaluate(
485.       ({ saveKey, writeBatches, writesPerBatch }) => {
486.         const raw = localStorage.getItem(saveKey);
487.         if (!raw) throw new Error(`Missing localStorage save: ${saveKey}`);
488.         const save = JSON.parse(raw);
489.         const serializeMs = [];
490.         const storageWriteMs = [];
491.         const combinedWriteMs = [];
492. 
493.         for (let batch = 0; batch < writeBatches; batch += 1) {
494.           let serialized = "";
495.           const startedAt = performance.now();
496.           for (let index = 0; index < writesPerBatch; index += 1) {
497.             save.timestamp += 1;
498.             serialized = JSON.stringify(save);
499.           }
500.           serializeMs.push(
501.             (performance.now() - startedAt) / writesPerBatch,
502.           );
503. 
504.           const storagePayloads = [];
505.           for (let index = 0; index < writesPerBatch; index += 1) {
506.             save.timestamp += 1;
507.             storagePayloads.push(JSON.stringify(save));
508.           }
509.           const storageStartedAt = performance.now();
510.           for (const payload of storagePayloads) {
511.             localStorage.setItem(saveKey, payload);
512.           }
513.           storageWriteMs.push(
514.             (performance.now() - storageStartedAt) / writesPerBatch,
515.           );
516. 
517.           const combinedStartedAt = performance.now();
518.           for (let index = 0; index < writesPerBatch; index += 1) {
519.             save.timestamp += 1;
520.             serialized = JSON.stringify(save);
521.             localStorage.setItem(saveKey, serialized);
522.           }
523.           combinedWriteMs.push(
524.             (performance.now() - combinedStartedAt) / writesPerBatch,
525.           );
526.         }
527.         return {
528.           raw,
529.           schemaVersion: save.version,
530.           bytes: new TextEncoder().encode(raw).byteLength,
531.           serializeMs,
532.           storageWriteMs,
533.           combinedWriteMs,
534.         };
535.       },
536.       {
537.         saveKey: SAVE_KEY,
538.         writeBatches: SAVE_WRITE_BATCHES,
539.         writesPerBatch: SAVE_WRITES_PER_BATCH,
540.       },
541.     );
542.   } finally {
543.     await context.close();
544.   }
545. }
