627. async function main() {
628.   const sampleCount = readSampleCount(process.env.PERFORMANCE_SAMPLES);
629.   const npmCli = process.env.npm_execpath;
630.   if (!npmCli) {
631.     throw new Error(
632.       "Missing npm_execpath; run the harness through "
633.       + "`npm run benchmark:baseline`.",
634.     );
635.   }
636.   const initialProvenance = await getGitProvenance();
637.   await runCommand(process.execPath, [npmCli, "run", "build"], {
638.     env: {
639.       ...process.env,
640.       VITE_BASE_PATH: BASE_PATH,
641.     },
642.   });
643. 
644.   const bundle = await measureBundle();
645.   const port = await findAvailablePort();
646.   const url = `http://127.0.0.1:${port}${BASE_PATH}`;
647.   const server = await startStaticServer(port);
648. 
649.   try {
650.     const browser = await chromium.launch({
651.       headless: true,
652.       args: [
653.         "--disable-background-timer-throttling",
654.         "--disable-backgrounding-occluded-windows",
655.         "--disable-renderer-backgrounding",
656.         "--enable-precise-memory-info",
657.         "--js-flags=--expose-gc",
658.       ],
659.     });
660.     try {
661.       const emptySaveSamples = [];
662.       for (let index = 0; index < sampleCount; index += 1) {
663.         emptySaveSamples.push(await measureStartup(browser, url, null));
664.       }
665. 
666.       const freshSave = await createFreshSave(browser, url);
667.       if (freshSave.schemaVersion !== 17) {
668.         throw new Error(
669.           `Expected fresh save schema v17, received v${freshSave.schemaVersion}`,
670.         );
671.       }
672. 
673.       const freshSaveSamples = [];
674.       for (let index = 0; index < sampleCount; index += 1) {
675.         freshSaveSamples.push(
676.           await measureStartup(browser, url, freshSave.raw),
677.         );
678.       }
679. 
680.       const result = {
681.         timestamp: new Date().toISOString(),
682.         commit: initialProvenance.commit,
683.         workingTree: {
684.           dirty: initialProvenance.dirty,
685.           diffHash: initialProvenance.diffHash,
686.         },
687.         environment: {
688.           platform: `${platform()} ${release()}`,
689.           arch: arch(),
690.           cpu: cpus()[0]?.model ?? "unknown",
691.           logicalCpus: cpus().length,
692.           totalMemoryBytes: totalmem(),
693.           node: process.version,
694.           chromium: browser.version(),
695.         },
696.         bundle,
697.         startup: {
698.           sampleCount,
699.           emptySave: summarizeStartup(emptySaveSamples),
700.           freshSave: summarizeStartup(freshSaveSamples),
701.         },
702.         save: {
703.           schemaVersion: freshSave.schemaVersion,
704.           bytes: freshSave.bytes,
705.           writeBatches: SAVE_WRITE_BATCHES,
706.           writesPerBatch: SAVE_WRITES_PER_BATCH,
707.           serializeMs: summarize(freshSave.serializeMs, 3),
708.           storageWriteMs: summarize(freshSave.storageWriteMs, 3),
709.           combinedWriteMs: summarize(freshSave.combinedWriteMs, 3),
710.         },
711.       };
712.       const finalProvenance = await getGitProvenance();
713.       assertMatchingProvenance(initialProvenance, finalProvenance);
714.       printReport(result);
715.     } finally {
716.       await browser.close();
717.     }
718.   } finally {
719.     await stopStaticServer(server);
720.   }
721. }
722. 
723. main().catch((error) => {
724.   const message = error instanceof Error ? error.message : String(error);
725.   console.error(`[performance-baseline] ${message}`);
726.   if (
727.     message.includes("Executable doesn't exist")
728.     || message.includes("browserType.launch")
729.   ) {
730.     console.error(
731.       "[performance-baseline] Install Chromium with "
732.       + "`npm run test:browser:install`.",
733.     );
734.   }
735.   process.exitCode = 1;
736. });

