9.     server.listen(0, "127.0.0.1", () => {
10.       const address = server.address();
11.       if (!address || typeof address === "string") {
12.         server.close();
13.         reject(new Error("Unable to allocate a browser test server port"));
14.         return;
15.       }
16.       server.close((error) => {
17.         if (error) reject(error);
18.         else resolve(address.port);
19.       });
20.     });
21.   });
22. }
